/// <summary>
/// Tín chỉ (44/43/99) và không xem theo niên chế → lấy OtherFinalSummary / OtherSummaryLearningMark.
/// Niên chế (04/09...) → lấy FinalSummary / SummaryLearningMark.
/// </summary>
private bool IsTinChiMark()
{
    return (intRegulationIDCurrent == 44 || intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99)
        && !chkXemTheoNienChe.Checked;
}

private string HtmlEncodeText(string strText)
{
    if (strText == null || strText.Length == 0)
        return "&nbsp;";
    return strText.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("\"", "&quot;");
}

private string FormatMarkHtml(object objValue, string strFormat, bool bolFail)
{
    if (objValue == null || objValue == DBNull.Value)
        return "<td>&nbsp;</td>";

    string strRaw = Convert.ToString(objValue);
    if (strRaw.Length < 1)
        return "<td>&nbsp;</td>";
    if (strRaw == "-1")
        return "<td>M</td>";

    string strValue = strRaw;
    try
    {
        double dbl = Convert.ToDouble(objValue);
        System.Globalization.CultureInfo cul = new System.Globalization.CultureInfo("vi-VN");
        strValue = dbl.ToString(strFormat, cul);
    }
    catch
    {
        strValue = strRaw;
    }

    if (bolFail)
        return "<td class='fail'>" + strValue + "</td>";
    return "<td>" + strValue + "</td>";
}

private bool IsMarkFailed(DataRow drw, int intIndex)
{
    string strPassCol = "Passed_" + intIndex.ToString();
    if (drw.Table.Columns.Contains(strPassCol) && drw[strPassCol] != DBNull.Value && Convert.ToString(drw[strPassCol]) != "")
    {
        try
        {
            return !Convert.ToBoolean(drw[strPassCol]);
        }
        catch
        {
            return false;
        }
    }
    return false;
}

private string GetReportHeaderText()
{
    string str = SystemService.SYS_SettingService.GetStringValue("Report_Header_Text");
    if (str == null || str.Length < 1)
        str = strReport_Header_Expand;
    return str == null ? "" : str;
}

private string GetReportHeader2Text()
{
    string str = SystemService.SYS_SettingService.GetStringValue("Report_Header2_Text");
    if (str == null || str.Length < 1)
        str = strReport_Header;
    return str == null ? "" : str;
}

private string BuildHtmlHeaderBlock()
{
    StringBuilder sb = new StringBuilder();
    sb.Append("<table class='header-table'><tr>");
    sb.Append("<td style='width:50%'>");
    sb.Append("<div class='school-name' style='font-weight:normal'>").Append(HtmlEncodeText(GetReportHeaderText())).Append("</div>");
    sb.Append("<div class='school-name'>").Append(HtmlEncodeText(GetReportHeader2Text())).Append("</div>");
    sb.Append("<div class='line'></div>");
    sb.Append("</td>");
    sb.Append("<td style='width:50%'>");
    sb.Append("<div class='motto'>CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM</div>");
    sb.Append("<div class='motto'>Độc lập - Tự do - Hạnh phúc</div>");
    sb.Append("<div class='line'></div>");
    sb.Append("</td>");
    sb.Append("</tr></table>");
    return sb.ToString();
}

private string BuildSubjectHeaderCells()
{
    StringBuilder sb = new StringBuilder();
    foreach (DataRow drw in dtbClassSubject.Rows)
    {
        string strName = Convert.ToString(drw["SubjectName"]);
        sb.Append("<th class='subject-name'>").Append(HtmlEncodeText(strName)).Append("</th>");
    }
    return sb.ToString();
}

private string BuildUnitTextHeaderCells()
{
    StringBuilder sb = new StringBuilder();
    foreach (DataRow drw in dtbClassSubject.Rows)
    {
        string strUnit = Convert.ToString(drw["UnitText"]);
        sb.Append("<th>").Append(HtmlEncodeText(strUnit)).Append("</th>");
    }
    return sb.ToString();
}

private string BuildStudentMarkCells(DataRow drw, bool bolTinChi, string strMarkFormat)
{
    StringBuilder sb = new StringBuilder();
    int iSoMon = dtbClassSubject.Rows.Count;
    for (int i = 1; i <= iSoMon; i++)
    {
        string strCol = bolTinChi
            ? ("OtherFinalSummary_" + i.ToString())
            : ("FinalSummary_" + i.ToString());

        object objVal = null;
        if (drw.Table.Columns.Contains(strCol))
            objVal = drw[strCol];

        sb.Append(FormatMarkHtml(objVal, strMarkFormat, IsMarkFailed(drw, i)));
    }
    return sb.ToString();
}

private string LoadHtmlTemplate(string strRelativePath, string strFallbackTitle)
{
    string strPath = Application.StartupPath + "\\" + strRelativePath;
    if (System.IO.File.Exists(strPath))
        return System.IO.File.ReadAllText(strPath, Encoding.UTF8);

    // Fallback nếu chưa copy mẫu vào thư mục chạy
    StringBuilder sb = new StringBuilder();
    sb.Append("<!DOCTYPE html><html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
    sb.Append("<title>").Append(strFallbackTitle).Append("</title>");
    sb.Append("<style type=\"text/css\">");
    sb.Append("body{font-family:'Times New Roman',Times,serif;font-size:11pt;margin:12px;}");
    sb.Append("table{border-collapse:collapse;}");
    sb.Append(".header-table,.info-table,.footer-table{width:100%;}");
    sb.Append(".school-name,.motto,.title,.subtitle{text-align:center;font-weight:bold;}");
    sb.Append(".line{border-bottom:1px solid #000;width:180px;margin:2px auto 0 auto;}");
    sb.Append(".title{font-size:14pt;margin:10px 0 4px 0;}");
    sb.Append(".note{font-size:10pt;font-style:italic;text-align:center;}");
    sb.Append(".mark-table{width:100%;border:1px solid #000;}");
    sb.Append(".mark-table th,.mark-table td{border:1px solid #000;padding:2px 3px;text-align:center;vertical-align:middle;}");
    sb.Append(".subject-name{writing-mode:vertical-rl;transform:rotate(180deg);height:160px;max-width:28px;font-weight:normal;font-size:9pt;}");
    sb.Append(".name-left{text-align:left!important;border-right:none!important;}");
    sb.Append(".name-right{text-align:left!important;border-left:none!important;}");
    sb.Append(".fail{background-color:#FFFF99;}");
    sb.Append(".sign-title{font-weight:bold;text-align:center;}");
    sb.Append("</style></head><body>{CONTENT}</body></html>");
    return sb.ToString();
}

private void SaveAndOpenHtml(string strFileName, string strContent)
{
    string strExportDir = Application.StartupPath + "\\Export";
    if (!System.IO.Directory.Exists(strExportDir))
        System.IO.Directory.CreateDirectory(strExportDir);

    string strClass = uClass.ClassName;
    if (strClass == null || strClass.Length < 1)
        strClass = Convert.ToString(uClass.ClassIDEditValue);
    strClass = strClass.Replace("\\", "_").Replace("/", "_").Replace(":", "_");

    string strFilePath = strExportDir + "\\" + strClass + "_" + strFileName;
    System.IO.File.WriteAllText(strFilePath, strContent, Encoding.UTF8);
    System.Diagnostics.Process.Start(strFilePath);
}

/// <summary>
/// Xuất HTML - Bảng tổng hợp kết quả học tập (cấu trúc giống Leaning_BangDiem_xQC44/QC09).
/// Số cột môn sinh động theo dtbClassSubject.
/// </summary>
private void ExportTongHopKQHT_HTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count < 1)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    bool bolTinChi = IsTinChiMark();
    string strMarkColFormat = "0.0";
    string strTbcFormat = bolTinChi ? "0.00" : "0.0";
    string strTbcField = bolTinChi ? "OtherSummaryLearningMark" : "SummaryLearningMark";

    StringBuilder sb = new StringBuilder();
    sb.Append(BuildHtmlHeaderBlock());
    sb.Append("<div class='title'>BẢNG TỔNG HỢP KẾT QUẢ HỌC TẬP HỌC SINH</div>");
    sb.Append("<div class='subtitle'>NĂM HỌC: ").Append(HtmlEncodeText(uYearSemester.YearEditValueText)).Append("</div>");

    sb.Append("<table class='info-table'>");
    sb.Append("<tr>");
    sb.Append("<td style='width:50%'>Lớp: <b>").Append(HtmlEncodeText(uClass.ClassName)).Append("</b></td>");
    sb.Append("<td style='width:50%'>Khóa: <b>").Append(HtmlEncodeText(uClass.CourseName)).Append("</b></td>");
    sb.Append("</tr><tr>");
    sb.Append("<td>Nghề: <b>").Append(HtmlEncodeText(uClass.BranchName)).Append("</b></td>");
    sb.Append("<td>Trình độ: <b>").Append(HtmlEncodeText(uClass.TrainingLevelName)).Append("</b></td>");
    sb.Append("</tr></table>");

    int iSoMon = dtbClassSubject.Rows.Count;
    int intColspanName = 2;
    int intRowSpanLeft = 2;

    sb.Append("<table class='mark-table'>");
    // Hàng 1: TT, Mã số, Họ và tên + tên môn dọc + Điểm TBC
    sb.Append("<tr>");
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>TT</th>");
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Mã số</th>");
    sb.Append("<th colspan='").Append(intColspanName.ToString()).Append("' rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Họ và tên</th>");
    sb.Append(BuildSubjectHeaderCells());
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Điểm TBC</th>");
    sb.Append("</tr>");
    // Hàng 2: số đơn vị học trình / tín chỉ
    sb.Append("<tr>");
    sb.Append(BuildUnitTextHeaderCells());
    sb.Append("</tr>");

    DataTable dtbSource = (gvData.DataSource as DataView).Table;
    int intSTT = 0;
    for (int r = 0; r < dtbSource.Rows.Count; r++)
    {
        DataRow drw = dtbSource.Rows[r];
        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td>").Append(intSTT.ToString()).Append("</td>");
        sb.Append("<td>").Append(HtmlEncodeText(Convert.ToString(drw["StudentCode"]))).Append("</td>");
        sb.Append("<td class='name-left'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentFirstName"]))).Append("</td>");
        sb.Append("<td class='name-right'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentLastName"]))).Append("</td>");
        sb.Append(BuildStudentMarkCells(drw, bolTinChi, strMarkColFormat));

        object objTbc = null;
        if (drw.Table.Columns.Contains(strTbcField))
            objTbc = drw[strTbcField];
        sb.Append(FormatMarkHtml(objTbc, strTbcFormat, false).Replace("<td>", "<td><b>").Replace("</td>", "</b></td>"));
        sb.Append("</tr>");
    }
    sb.Append("</table>");

    DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
    string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
    if (strPlace == null || strPlace.Length < 1)
        strPlace = strReport_Place;
    string strPrintDate = (strPlace == null ? "" : strPlace)
        + ", ngày " + dtmNow.Day.ToString()
        + " tháng " + dtmNow.Month.ToString()
        + " năm " + dtmNow.Year.ToString();

    sb.Append("<table class='footer-table'><tr>");
    sb.Append("<td style='width:33%;text-align:left;padding-left:20px;'><b>Tổng cộng:</b> ")
        .Append(dtbSource.Rows.Count.ToString()).Append(" học sinh</td>");
    sb.Append("<td style='width:33%'><div class='sign-title'>PHÒNG ĐÀO TẠO</div></td>");
    sb.Append("<td style='width:34%'><div>").Append(HtmlEncodeText(strPrintDate)).Append("</div>");
    sb.Append("<div class='sign-title' style='margin-top:8px;'>NGƯỜI LẬP</div></td>");
    sb.Append("</tr></table>");

    string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_TongHopKQHT.htm", "Bảng tổng hợp kết quả học tập");
    string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());
    SaveAndOpenHtml("BangDiem_TongHopKQHT.htm", strFileContent);
}

