        Application.StartupPath + "\\" + strRelativePath,
        Application.StartupPath + "\\..\\..\\" + strRelativePath,
        Application.StartupPath + "\\..\\..\\..\\" + strRelativePath
    };

    for (int i = 0; i < arrPaths.Length; i++)
    {
        try
        {
            string strFull = System.IO.Path.GetFullPath(arrPaths[i]);
            if (System.IO.File.Exists(strFull))
                return System.IO.File.ReadAllText(strFull, Encoding.UTF8);
        }
        catch
        {
        }
    }

    // Fallback nếu chưa copy mẫu vào thư mục chạy
    StringBuilder sb = new StringBuilder();
    sb.Append("<!DOCTYPE html><html><head><meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />");
    sb.Append("<title>").Append(strFallbackTitle).Append("</title>");
