/// <summary>
/// Xuất HTML - Bảng tổng hợp kết quả học tập (cấu trúc giống Leaning_BangDiem_xQC44/QC09).
/// Số cột môn sinh động theo dtbClassSubject. Cắt trang thủ công để mỗi trang có đủ tiêu đề cột.
/// </summary>
private void ExportTongHopKQHT_HTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count < 1)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    bool bolTinChi = IsTinChiMark();
    string strMarkColFormat = "0.0";
    string strTbcFormat = bolTinChi ? "0.00" : "0.0";
    string strTbcField = bolTinChi ? "OtherSummaryLearningMark" : "SummaryLearningMark";

    DataTable dtbSource = dtbData;
    if (gvData.DataSource is DataView)
        dtbSource = (gvData.DataSource as DataView).Table;
    if (dtbSource == null || dtbSource.Rows.Count < 1)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
    string strPlace = SystemService.SYS_SettingService.GetStringValue("Report_Place");
    if (strPlace == null || strPlace.Length < 1)
        strPlace = strReport_Place;
    string strPrintDate = (strPlace == null ? "" : strPlace)
        + ", ngày " + dtmNow.Day.ToString()
        + " tháng " + dtmNow.Month.ToString()
        + " năm " + dtmNow.Year.ToString();

    int intRowsPerPage = GetHtmlMarkRowsPerPage();
    int intTotal = dtbSource.Rows.Count;
    int intPageCount = (intTotal + intRowsPerPage - 1) / intRowsPerPage;
    string strTableHeader = BuildTongHopMarkTableHeaderHtml();

    StringBuilder sb = new StringBuilder();
    for (int intPage = 0; intPage < intPageCount; intPage++)
    {
        bool bolLastPage = (intPage == intPageCount - 1);
        sb.Append("<div class='print-page").Append(bolLastPage ? " last-page" : "").Append("'>");

        sb.Append(BuildHtmlHeaderBlock());
        sb.Append("<div class='title'>BẢNG TỔNG HỢP KẾT QUẢ HỌC TẬP HỌC SINH</div>");
        sb.Append("<div class='subtitle'>NĂM HỌC: ").Append(HtmlEncodeText(uYearSemester.YearEditValueText)).Append("</div>");
        sb.Append(BuildTongHopInfoBlockHtml());

        sb.Append("<table class='mark-table'>");
        sb.Append(strTableHeader);
        sb.Append("<tbody>");

        int intFrom = intPage * intRowsPerPage;
        int intTo = intFrom + intRowsPerPage;
        if (intTo > intTotal)
            intTo = intTotal;

        for (int r = intFrom; r < intTo; r++)
        {
            DataRow drw = dtbSource.Rows[r];
            int intSTT = r + 1;
            sb.Append("<tr>");
            sb.Append("<td>").Append(intSTT.ToString()).Append("</td>");
            sb.Append("<td>").Append(HtmlEncodeText(Convert.ToString(drw["StudentCode"]))).Append("</td>");
            sb.Append("<td class='name-left'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentFirstName"]))).Append("</td>");
            sb.Append("<td class='name-right'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentLastName"]))).Append("</td>");
            sb.Append(BuildStudentMarkCells(drw, bolTinChi, strMarkColFormat));

            object objTbc = null;
            if (drw.Table.Columns.Contains(strTbcField))
                objTbc = drw[strTbcField];
            string strTbcCell = FormatMarkHtml(objTbc, strTbcFormat, false);
            strTbcCell = strTbcCell.Replace("<td>", "<td><b>").Replace("</td>", "</b></td>");
            sb.Append(strTbcCell);
            sb.Append("</tr>");
        }
        sb.Append("</tbody></table>");

        if (bolLastPage)
        {
            sb.Append("<table class='footer-table' style='width:100%;margin-top:16px;'>");
            sb.Append("<tr>");
            sb.Append("<td style='width:33%;text-align:left;padding-left:20px;vertical-align:top;' rowspan='2'><b>Tổng cộng:</b> ")
                .Append(intTotal.ToString()).Append(" học sinh</td>");
            sb.Append("<td style='width:33%;'></td>");
            sb.Append("<td style='width:34%;text-align:center;vertical-align:top;'>").Append(HtmlEncodeText(strPrintDate)).Append("</td>");
            sb.Append("</tr>");
            sb.Append("<tr>");
            sb.Append("<td style='width:33%;text-align:center;font-weight:bold;padding-top:8px;'>PHÒNG ĐÀO TẠO</td>");
            sb.Append("<td style='width:34%;text-align:center;font-weight:bold;padding-top:8px;'>NGƯỜI LẬP</td>");
            sb.Append("</tr></table>");
        }

        sb.Append("</div>");
    }

    string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_TongHopKQHT.htm", "Bảng tổng hợp kết quả học tập");
    string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());
    SaveAndOpenHtml("BangDiem_TongHopKQHT.htm", strFileContent);
}

