/// <summary>
/// Xuất HTML - DS công nhận kết quả học tập (cấu trúc giống Leaning_BangDiem_NienHoc_xQC44A3/QC09A3).
/// Có thêm cột Xếp loại; số cột môn sinh động.
/// </summary>
private void ExportCongNhanKQHT_HTML()
{
    if (dtbData == null || dtbClassSubject == null || dtbClassSubject.Rows.Count < 1)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    bool bolTinChi = IsTinChiMark();
    string strMarkColFormat = "0.0";
    string strTbcFormat = "0.0";
    string strTbcField = bolTinChi ? "OtherSummaryLearningMark" : "SummaryLearningMark";

    StringBuilder sb = new StringBuilder();
    sb.Append(BuildHtmlHeaderBlock());
    sb.Append("<div class='title'>DANH SÁCH CÔNG NHẬN KẾT QUẢ HỌC TẬP HỌC SINH</div>");

    string strSemester = "";
    if (uYearSemester.SemesterEditValue != null)
        strSemester = Convert.ToString(uYearSemester.SemesterEditValue);

    sb.Append("<div class='subtitle'>HỌC KÌ ").Append(HtmlEncodeText(strSemester))
        .Append(" NĂM HỌC ").Append(HtmlEncodeText(uYearSemester.YearEditValueText)).Append("</div>");
    sb.Append("<div class='note'>(Kèm theo Quyết định số ../QĐ-TCCN8 ngày ….tháng … năm ... của Hiệu trưởng Trường Trung cấp Công nghệ số 8 Nam Định)</div>");

    sb.Append("<div class='info-wrap' style='width:100%;text-align:center;margin-bottom:8px;'>");
    sb.Append("<table class='info-table' style='width:auto;margin:0 auto;text-align:left;'>");
    sb.Append("<tr>");
    sb.Append("<td style='padding:2px 18px;white-space:nowrap;'>Lớp học: <b>").Append(HtmlEncodeText(uClass.ClassName)).Append("</b></td>");
    sb.Append("<td style='padding:2px 18px;white-space:nowrap;'>Khóa: <b>").Append(HtmlEncodeText(uClass.CourseName)).Append("</b></td>");
    sb.Append("</tr><tr>");
    sb.Append("<td style='padding:2px 18px;white-space:nowrap;'>Nghề: <b>").Append(HtmlEncodeText(uClass.BranchName)).Append("</b></td>");
    sb.Append("<td style='padding:2px 18px;white-space:nowrap;'>Trình độ: <b>").Append(HtmlEncodeText(uClass.TrainingLevelName)).Append("</b></td>");
    sb.Append("</tr></table></div>");

    int intRowSpanLeft = 2;
    sb.Append("<table class='mark-table'>");
    sb.Append("<thead>");
    sb.Append("<tr>");
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>TT</th>");
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Mã HS</th>");
    sb.Append("<th colspan='2' rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Họ và tên học sinh</th>");
    sb.Append(BuildSubjectHeaderCells());
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("' class='subject-name'>Điểm TBC</th>");
    sb.Append("<th rowspan='").Append(intRowSpanLeft.ToString()).Append("'>Xếp loại</th>");
    sb.Append("</tr>");
    sb.Append("<tr>");
    sb.Append(BuildUnitTextHeaderCells());
    sb.Append("</tr>");
    sb.Append("</thead><tbody>");

    DataTable dtbSource = dtbData;
    if (gvData.DataSource is DataView)
        dtbSource = (gvData.DataSource as DataView).Table;
    if (dtbSource == null || dtbSource.Rows.Count < 1)
    {
        MessageManager.Warning("Không có dữ liệu để xuất!");
        return;
    }

    int intSTT = 0;
    for (int r = 0; r < dtbSource.Rows.Count; r++)
    {
        DataRow drw = dtbSource.Rows[r];
        intSTT++;
        sb.Append("<tr>");
        sb.Append("<td>").Append(intSTT.ToString()).Append("</td>");
        sb.Append("<td>").Append(HtmlEncodeText(Convert.ToString(drw["StudentCode"]))).Append("</td>");
        sb.Append("<td class='name-left'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentFirstName"]))).Append("</td>");
        sb.Append("<td class='name-right'>").Append(HtmlEncodeText(Convert.ToString(drw["StudentLastName"]))).Append("</td>");
        sb.Append(BuildStudentMarkCells(drw, bolTinChi, strMarkColFormat));

        object objTbc = null;
        if (drw.Table.Columns.Contains(strTbcField))
            objTbc = drw[strTbcField];
        sb.Append(FormatMarkHtml(objTbc, strTbcFormat, false));

        string strLevel = "";
        if (drw.Table.Columns.Contains("LearningLevel"))
            strLevel = Convert.ToString(drw["LearningLevel"]);
        sb.Append("<td>").Append(HtmlEncodeText(strLevel)).Append("</td>");
        sb.Append("</tr>");
    }
    sb.Append("</tbody></table>");

    sb.Append("<table class='footer-table'><tr>");
    sb.Append("<td><b>Tổng cộng có:</b> ").Append(dtbSource.Rows.Count.ToString()).Append(" học sinh</td>");
    sb.Append("</tr></table>");

    string strTemplate = LoadHtmlTemplate("MauHtml\\BangDiem\\BangDiem_CongNhanKQHT.htm", "DS công nhận kết quả học tập");
    string strFileContent = strTemplate.Replace("{CONTENT}", sb.ToString());
    SaveAndOpenHtml("BangDiem_CongNhanKQHT.htm", strFileContent);
}

